#include <iostream>
#include <iomanip>

using namespace std;

void ChipsAllSlots(int numChips) {
    const int NUM_SLOTS = 9;
    const int slotWinnings[NUM_SLOTS] = {100, 500, 1000, 0, 10000, 0, 1000, 500, 100};

    for (int i = 0; i < numChips; ++i) {
